//! `gex-project.json`: what an ejected project is. Generated by `gexc eject`,
//! read by `gexc eject build` and `gexc eject run`. The user does not edit it
//! (their settings are `user/eject.json`, see [`crate::config`]).

use crate::json::{self, field, obj, opt_str, str_field, str_list, Json};
use anyhow::{anyhow, bail, Context, Result};
use std::path::{Path, PathBuf};

pub const PROJECT_FILE: &str = "gex-project.json";
pub const FORMAT: &str = "gex-eject-project";
pub const VERSION: u64 = 1;

/// The program the project runs by default.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Program {
    /// Guest path of the executable.
    pub exe: String,
    pub argv: Vec<String>,
    pub env: Vec<String>,
    pub cwd: Option<String>,
}

/// One object of the closure, stored under `rootfs/` at its guest path.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Object {
    /// `sha256:<hex>` of the file.
    pub id: String,
    /// Guest path.
    pub path: String,
    /// `exe`, `interp` or `library`.
    pub role: String,
    pub size: u64,
}

/// A data file the session read, stored under `rootfs/` at its guest path.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct File {
    pub path: String,
    pub id: String,
    pub size: u64,
}

#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Project {
    pub isa: String,
    pub program: Program,
    pub objects: Vec<Object>,
    pub files: Vec<File>,
    /// Directories the session opened or ran in, created in `rootfs/`.
    pub dirs: Vec<String>,
    /// Paths the session probed and did not find. They stay missing.
    pub missing: Vec<String>,
    /// Files the session created or only wrote: its output, not its input.
    pub outputs: Vec<String>,
    /// The session this was ejected from: the hashes of its two files.
    pub session_id: String,
    pub profile_id: Option<String>,
    /// Syscall names the session made, for the reader (the slim runtime of
    /// eject v1 trims to them).
    pub syscalls: Vec<String>,
    pub processes: u64,
    pub threads: u64,
    pub exit: Option<String>,
    /// The runtime copied to `runtime/gexc`: its hash and build fingerprint.
    pub runtime_id: String,
    pub runtime_build: Option<String>,
}

/// A guest path as a relative path under `rootfs/`, refusing anything that
/// could climb out of it.
pub fn rootfs_rel(guest: &str) -> Result<PathBuf> {
    if !guest.starts_with('/') {
        bail!("{guest:?} is not an absolute guest path");
    }
    let mut p = PathBuf::from("rootfs");
    for c in guest.split('/').filter(|c| !c.is_empty() && *c != ".") {
        if c == ".." {
            bail!("guest path {guest:?} climbs with `..`; refusing to place it");
        }
        p.push(c);
    }
    Ok(p)
}

impl Project {
    pub fn exe(&self) -> Result<&Object> {
        self.objects
            .iter()
            .find(|o| o.path == self.program.exe)
            .ok_or_else(|| anyhow!("the project's program {} is not among its objects", self.program.exe))
    }

    pub fn to_json(&self) -> String {
        let objects = self
            .objects
            .iter()
            .map(|o| {
                obj(vec![
                    ("id", json::s(&o.id)),
                    ("path", json::s(&o.path)),
                    ("role", json::s(&o.role)),
                    ("size", json::n(o.size)),
                ])
            })
            .collect();
        let files = self
            .files
            .iter()
            .map(|f| obj(vec![("path", json::s(&f.path)), ("id", json::s(&f.id)), ("size", json::n(f.size))]))
            .collect();
        json::write(&obj(vec![
            ("format", json::s(FORMAT)),
            ("version", json::n(VERSION)),
            (
                "note",
                json::s(
                    "Generated by gexc eject; regenerated on every re-eject. Your settings \
                     go in user/eject.json. See docs/eject.md in gex.",
                ),
            ),
            ("isa", json::s(&self.isa)),
            (
                "program",
                obj(vec![
                    ("exe", json::s(&self.program.exe)),
                    ("argv", json::strs(&self.program.argv)),
                    ("env", json::strs(&self.program.env)),
                    ("cwd", json::opt(self.program.cwd.as_ref())),
                ]),
            ),
            ("objects", Json::Arr(objects)),
            ("files", Json::Arr(files)),
            ("dirs", json::strs(&self.dirs)),
            ("missing", json::strs(&self.missing)),
            ("outputs", json::strs(&self.outputs)),
            (
                "session",
                obj(vec![
                    ("id", json::s(&self.session_id)),
                    ("profile", json::opt(self.profile_id.as_ref())),
                    ("syscalls", json::strs(&self.syscalls)),
                    ("processes", json::n(self.processes)),
                    ("threads", json::n(self.threads)),
                    ("exit", json::opt(self.exit.as_ref())),
                ]),
            ),
            (
                "runtime",
                obj(vec![
                    ("gexc", json::s(&self.runtime_id)),
                    ("build", json::opt(self.runtime_build.as_ref())),
                ]),
            ),
        ]))
    }

    pub fn from_json(text: &str) -> Result<Project> {
        let what = PROJECT_FILE;
        let v = Json::parse(text).map_err(|e| anyhow!("{what}: {e}"))?;
        if str_field(&v, "format", what)? != FORMAT {
            bail!("{what}: not a gex-eject project");
        }
        let version = field(&v, "version", what)?.as_u64();
        if version != Some(VERSION) {
            bail!("{what}: version {version:?}; this gexc reads version {VERSION}");
        }
        let prog = field(&v, "program", what)?;
        let program = Program {
            exe: str_field(prog, "exe", what)?,
            argv: str_list(prog, "argv", what)?,
            env: str_list(prog, "env", what)?,
            cwd: opt_str(prog, "cwd"),
        };
        let list = |k: &str| -> Result<Vec<&Json>> {
            Ok(field(&v, k, what)?
                .as_arr()
                .ok_or_else(|| anyhow!("{what}: \"{k}\" is not a list"))?
                .iter()
                .collect())
        };
        let mut objects = Vec::new();
        for o in list("objects")? {
            objects.push(Object {
                id: str_field(o, "id", what)?,
                path: str_field(o, "path", what)?,
                role: str_field(o, "role", what)?,
                size: field(o, "size", what)?.as_u64().unwrap_or(0),
            });
        }
        let mut files = Vec::new();
        for f in list("files")? {
            files.push(File {
                path: str_field(f, "path", what)?,
                id: str_field(f, "id", what)?,
                size: field(f, "size", what)?.as_u64().unwrap_or(0),
            });
        }
        let session = field(&v, "session", what)?;
        let runtime = field(&v, "runtime", what)?;
        Ok(Project {
            isa: str_field(&v, "isa", what)?,
            program,
            objects,
            files,
            dirs: str_list(&v, "dirs", what)?,
            missing: str_list(&v, "missing", what)?,
            outputs: str_list(&v, "outputs", what)?,
            session_id: str_field(session, "id", what)?,
            profile_id: opt_str(session, "profile"),
            syscalls: str_list(session, "syscalls", what)?,
            processes: session.get("processes").and_then(Json::as_u64).unwrap_or(0),
            threads: session.get("threads").and_then(Json::as_u64).unwrap_or(0),
            exit: opt_str(session, "exit"),
            runtime_id: str_field(runtime, "gexc", what)?,
            runtime_build: opt_str(runtime, "build"),
        })
    }

    pub fn load(dir: &Path) -> Result<Project> {
        let p = dir.join(PROJECT_FILE);
        let text = std::fs::read_to_string(&p)
            .with_context(|| format!("reading {} (is {} an ejected project?)", p.display(), dir.display()))?;
        Project::from_json(&text)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips() {
        let p = Project {
            isa: "aarch64".into(),
            program: Program {
                exe: "/bin/x".into(),
                argv: vec!["/bin/x".into(), "5".into()],
                env: vec!["A=b".into()],
                cwd: Some("/".into()),
            },
            objects: vec![Object {
                id: "sha256:00".into(),
                path: "/bin/x".into(),
                role: "exe".into(),
                size: 3,
            }],
            files: vec![File { path: "/etc/a".into(), id: "sha256:11".into(), size: 1 }],
            dirs: vec!["/".into()],
            missing: vec!["/etc/nope".into()],
            outputs: vec![],
            session_id: "sha256:22".into(),
            profile_id: None,
            syscalls: vec!["write".into()],
            processes: 1,
            threads: 1,
            exit: Some("status 0".into()),
            runtime_id: "sha256:33".into(),
            runtime_build: None,
        };
        let text = p.to_json();
        assert_eq!(Project::from_json(&text).unwrap(), p);
    }

    #[test]
    fn guest_paths_stay_inside_the_rootfs() {
        assert_eq!(rootfs_rel("/a/./b").unwrap(), PathBuf::from("rootfs/a/b"));
        assert!(rootfs_rel("/a/../../etc").is_err());
        assert!(rootfs_rel("relative").is_err());
    }
}
